CREATE POLICY "Users read own work docs" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'work-docs' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "Users upload own work docs" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'work-docs' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "Users update own work docs" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'work-docs' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "Users delete own work docs" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'work-docs' AND (storage.foldername(name))[1] = auth.uid()::text);